#!/usr/bin/env bash
# mf-free-tools static v1: serve all 102 tools as static files at https://mfaysal.com/free-tools/<slug>/
# Installs public/free-tools/ (pages, assets, /free-tools/vendor AI engine, /free-tools/models AI models, own .htaccess with CSP).
# Nothing in app/, routes or the database is touched. The PHP router never sees /free-tools/* because real files/dirs are served first.
# Needs (same folder as this script): mf-free-tools-v1-vendor.tar.gz and mf-free-tools-v1-models.tar.gz.part-* (or SKIP_AI=1).
# Usage: bash deploy.sh --dry-run   then   bash deploy.sh
# Env: SITE (default /home/photoret/mfaysal.com)  SMOKE=0  SKIP_AI=1  ROBOTS=0 (don't add the sitemap line)  RELINK=1 (also rewrite
#      uk-calculators.vercel.app links in app/views/*.php to /free-tools/, with backups)
set -uo pipefail
PKG="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"; cd "$PKG"
SITE="${SITE:-/home/photoret/mfaysal.com}"; SITE="${SITE%/}"; PUB="$SITE/public"; DEST="$PUB/free-tools"
TAG="bak-20261015fs"; MAN="$PKG/manifest-20261015fs.txt"; DRY=0; SMOKE="${SMOKE:-1}"; SKIP_AI="${SKIP_AI:-0}"; ROBOTS="${ROBOTS:-1}"; RELINK="${RELINK:-0}"
[ "${1:-}" = "--dry-run" ] && DRY=1
for f in "$PKG"/../mf-free-tools-v1-vendor.tar.gz "$PKG"/../mf-free-tools-v1-models.tar.gz.part-*; do [ -e "$f" ] && mv -n "$f" "$PKG/"; done
die(){ echo "ERROR: $*. Nothing changed."; exit 2; }
[ -f "$PUB/index.php" ] && [ -f "$PUB/.htaccess" ] || die "$PUB/index.php or .htaccess not found (set SITE=...)"
[ -d "$PKG/free-tools" ] && [ -f "$PKG/free-tools/index.html" ] && [ -f "$PKG/free-tools/.htaccess" ] || die "package folder free-tools/ missing (extract the core tar.gz first)"
grep -q 'REQUEST_FILENAME} !-d' "$PUB/.htaccess" || echo "  WARNING: public/.htaccess has no '!-d' check; /free-tools/ may still reach PHP. The smoke test will catch it."
if [ "$SKIP_AI" != 1 ]; then
  [ -f "$PKG/mf-free-tools-v1-vendor.tar.gz" ] || die "mf-free-tools-v1-vendor.tar.gz missing next to deploy.sh (or SKIP_AI=1)"
  ls "$PKG"/mf-free-tools-v1-models.tar.gz.part-* >/dev/null 2>&1 || die "mf-free-tools-v1-models.tar.gz.part-* missing next to deploy.sh (or SKIP_AI=1)"
fi
FREE=$(df -Pk "$PUB" | awk 'NR==2{print $4}'); [ "${FREE:-0}" -gt 600000 ] || die "less than 600 MB free on $PUB"
echo "  target  : $DEST $([ -e "$DEST" ] && echo '(exists: it will be moved to free-tools.'$TAG')' || echo '(new)')"
echo "  pages   : $(find "$PKG/free-tools" -name index.html | wc -l) index.html files"
[ "$ROBOTS" = 1 ] && { [ -f "$PUB/robots.txt" ] && { grep -q "free-tools/sitemap.xml" "$PUB/robots.txt" && echo "  robots  : up to date" || echo "  robots  : will add 'Sitemap: https://mfaysal.com/free-tools/sitemap.xml'"; } || echo "  robots  : public/robots.txt is not a file (generated by PHP?). Skipping; submit the sitemap in Search Console instead."; }
[ "$RELINK" = 1 ] && echo "  relink  : $(grep -rl 'uk-calculators\.vercel\.app' "$SITE/app/views" 2>/dev/null | wc -l) view file(s) contain uk-calculators.vercel.app links"
[ $DRY = 1 ] && { echo "DRY RUN: nothing changed."; exit 0; }
STAGE="$PUB/free-tools.new-$TAG"; rm -rf "$STAGE"; mkdir -p "$STAGE"
cp -a "$PKG/free-tools/." "$STAGE/" || { rm -rf "$STAGE"; die "copy failed"; }
if [ "$SKIP_AI" != 1 ]; then
  tar xzf "$PKG/mf-free-tools-v1-vendor.tar.gz" -C "$STAGE" || { rm -rf "$STAGE"; die "vendor extract failed"; }
  cat "$PKG"/mf-free-tools-v1-models.tar.gz.part-* | tar xz -C "$STAGE" || { rm -rf "$STAGE"; die "models extract failed (are all parts uploaded?)"; }
fi
( cd "$STAGE" && sha256sum -c --quiet "$PKG/SHA256SUMS" 2>/dev/null ) || { [ "$SKIP_AI" = 1 ] && ( cd "$STAGE" && grep -vE ' \./(vendor|models)/' "$PKG/SHA256SUMS" | sha256sum -c --quiet ) ; } || { rm -rf "$STAGE"; die "checksum verification failed"; }
echo "  checksums OK"
find "$STAGE" -type d -exec chmod 755 {} + ; find "$STAGE" -type f -exec chmod 644 {} +
: > "$MAN.tmp"; [ -f "$MAN" ] && cat "$MAN" > "$MAN.tmp"
if grep -qE "^(DIR|NEWDIR) " "$MAN.tmp"; then
  # re-run: the live folder is from this package, the original backup (if any) is kept untouched
  [ -e "$DEST" ] && { rm -rf "$DEST.old-$TAG"; mv "$DEST" "$DEST.old-$TAG"; }
elif [ -e "$DEST" ]; then mv "$DEST" "$PUB/free-tools.$TAG" && echo "DIR $PUB/free-tools.$TAG" >> "$MAN.tmp"
else echo "NEWDIR $DEST" >> "$MAN.tmp"; fi
mv "$STAGE" "$DEST" && echo "  installed $DEST"; rm -rf "$DEST.old-$TAG"
mv "$MAN.tmp" "$MAN"
bak(){ grep -qxF "BAK $1" "$MAN" || { cp -p "$1" "$1.$TAG"; echo "BAK $1" >> "$MAN"; }; }
if [ "$ROBOTS" = 1 ] && [ -f "$PUB/robots.txt" ] && ! grep -q "free-tools/sitemap.xml" "$PUB/robots.txt"; then bak "$PUB/robots.txt"; printf '\nSitemap: https://mfaysal.com/free-tools/sitemap.xml\n' >> "$PUB/robots.txt"; echo "  robots.txt: sitemap added"; fi
if [ "$RELINK" = 1 ]; then for f in $(grep -rl 'uk-calculators\.vercel\.app' "$SITE/app/views" 2>/dev/null); do bak "$f"; sed -i 's#https://uk-calculators\.vercel\.app/\?#/free-tools/#g' "$f"; echo "  relinked $f"; done; fi
[ "$SMOKE" = 1 ] || { echo "Smoke test skipped. Roll back: bash $PKG/restore.sh"; exit 0; }
echo "== smoke test"; FAIL=0; UA="Mozilla/5.0 mf-deploy"
chk(){ local u="$1" want="${2:-200}" c; c=$(curl -s -o /dev/null -w '%{http_code}' -A "$UA" "https://mfaysal.com$u?nocache=$RANDOM" || echo 000); echo "  $u -> $c"; [ "$c" = "$want" ] || FAIL=1; }
for u in /free-tools/ /free-tools/background-remover/ /free-tools/take-home-pay-calculator/ /free-tools/uuid-generator/ /free-tools/webcam-test/ /free-tools/sitemap.xml /free-tools/assets/style.css /free-tools/assets/tools.js /free-tools/og/background-remover.png; do chk $u; done
[ "$SKIP_AI" = 1 ] || for u in /free-tools/vendor/transformers-4.3.1.min.js /free-tools/vendor/ort/ort-wasm-simd-threaded.jsep.wasm /free-tools/models/Xenova/modnet/config.json; do chk $u; done
chk /free-tools/no-such-tool/ 404
for u in / /blog /about; do c=$(curl -s -o /dev/null -w '%{http_code}' -A "$UA" "https://mfaysal.com$u"); echo "  $u -> $c (site)"; case $c in 5*) FAIL=1;; esac; done
H=$(curl -sI -A "$UA" https://mfaysal.com/free-tools/background-remover/)
echo "$H" | grep -qi "content-type: text/html" || { echo "  /free-tools/ page is not served as HTML"; FAIL=1; }
echo "$H" | grep -i "^content-security-policy" | grep -q "wasm-unsafe-eval" && echo "  CSP header OK" || echo "  WARNING: free-tools CSP header not seen (mod_headers off?). Pages still work."
[ "$(echo "$H" | grep -ci '^permissions-policy')" = 1 ] && echo "$H" | grep -qi "camera=(self)" && echo "  Permissions-Policy OK (camera/mic allowed for tools)" || echo "  WARNING: Permissions-Policy not overridden; webcam/mic/recorder tools will be blocked. See README."
curl -s -A "$UA" https://mfaysal.com/free-tools/ | grep -q 'id="tools"' || { echo "  hub HTML not ours (router caught it?)"; FAIL=1; }
[ $FAIL = 0 ] || { echo "Smoke test FAILED -> rolling back"; bash "$PKG/restore.sh"; exit 1; }
echo "Done. Live: https://mfaysal.com/free-tools/ . Roll back: bash $PKG/restore.sh"
